                const x = (va ^ vb);
                if ((x != 0)) {
                    return (i + (if (comptime @typeInfo(@TypeOf((@clz(x) / 8))) == .@"enum") cp_cast_int(usize, @intFromEnum((@clz(x) / 8))) else cp_cast_int(usize, (@clz(x) / 8))));
                }
                i = (i + 8);
            }
            while (((i < n) and (sa[@as(usize, @intCast(((n - 1) - i)))] == sb[@as(usize, @intCast(((n - 1) - i)))]))) {
                i = (i + 1);
            }
            return i;
        } else {
            var i: usize = 0;
            _ = &i;
            while (((i < n) and (a[@as(usize, @intCast(((a.len - 1) - i)))] == b[@as(usize, @intCast(((b.len - 1) - i)))]))) {
                i = (i + 1);
            }
            return i;
        }
}

pub fn diagRange(d: i32, n: i32, m: i32) DiagBounds {
        var lo = (-d);
        _ = &lo;
        if ((lo < (-m))) {
            lo = ((-m) + ((d - m) & 1));
        }
        var hi = d;
        _ = &hi;
        if ((hi > n)) {
            hi = (n - ((d - n) & 1));
        }
        return DiagBounds{ .lo = lo, .hi = hi };
}

pub fn Myers(comptime T: type) type {
        return struct {
    allocator: std.mem.Allocator,
    a: []const T,
    b: []const T,
    sc: *MyersScratch,
    policy: Policy,
    work_left: isize,
    anchors: ?Anchors,

pub fn init(allocator: std.mem.Allocator, a: []const T, b: []const T, sc: *MyersScratch, policy: Policy) @This() {
            return @This(){ .allocator = allocator, .a = a, .b = b, .sc = sc, .policy = policy, .work_left = @as(isize, @intCast(policy.work)), .anchors = null };
    }

pub fn deinit(self: *@This()) void {
            if (self.anchors) |*an| {
                _ = &an;
                _ = (an.*).__cp_deinit();
                self.anchors = null;
            }
    }

pub fn run(self: *@This(), a_start: usize, a_end: usize, b_start: usize, b_end: usize, changed_a: []bool, changed_b: []bool) void {
            _ = self.sc.stack.clearRetainingCapacity();
            _ = bun.handleOom(self.sc.stack.append(self.allocator, Job{ .alo = a_start, .ahi = a_end, .blo = b_start, .bhi = b_end, .probe = self.policy.probe, .exhaustive = true }));
            while (self.sc.stack.pop()) |job| {
                var alo = job.alo;
                _ = &alo;
                var ahi = job.ahi;
                _ = &ahi;
                var blo = job.blo;
                _ = &blo;
                var bhi = job.bhi;
                _ = &bhi;
                const probe = job.probe;
                const exhaustive = job.exhaustive;
                const p = commonPrefix(T, self.a[alo..ahi], self.b[blo..bhi]);
                alo = (alo + p);
                blo = (blo + p);
                const s = commonSuffix(T, self.a[alo..ahi], self.b[blo..bhi]);
                ahi = (ahi - s);
                bhi = (bhi - s);
                if ((alo == ahi)) {
                    _ = @memset(changed_b[blo..bhi], true);
                    continue;
                }
                if ((blo == bhi)) {
                    _ = @memset(changed_a[alo..ahi], true);
                    continue;
                }
                if (((ahi - alo) == 1)) {
                    const x = self.a[@as(usize, @intCast(alo))];
                    _ = @memset(changed_b[blo..bhi], true);
                    var found: ?usize = null;
                    _ = &found;
                    var j: usize = 0;
                    _ = &j;
                    for (cp_iter_slice(self.b[blo..bhi])) |y| {
                        _ = &y;
                        if ((y == x)) {
                            found = j;
                            break;
                        }
                        j = (j + 1);
                    }
                    if (found) |fj| {
                        _ = &fj;
                        changed_b[cp_cast_int(usize, (blo + fj))] = false;
                    } else {
                        changed_a[cp_cast_int(usize, alo)] = true;
                    }
                    continue;
                }
                if (((bhi - blo) == 1)) {
                    const y = self.b[@as(usize, @intCast(blo))];
                    _ = @memset(changed_a[alo..ahi], true);
                    var found: ?usize = null;
                    _ = &found;
                    var i: usize = 0;
                    _ = &i;
                    for (cp_iter_slice(self.a[alo..ahi])) |x| {
                        _ = &x;
                        if ((x == y)) {
                            found = i;
                            break;
                        }
                        i = (i + 1);
                    }
                    if (found) |fi| {
                        _ = &fi;
                        changed_a[cp_cast_int(usize, (alo + fi))] = false;
                    } else {
                        changed_b[cp_cast_int(usize, blo)] = true;
                    }
                    continue;
                }
                if ((self.work_left <= 0)) {
                    _ = @memset(changed_a[alo..ahi], true);
                    _ = @memset(changed_b[blo..bhi], true);
                    continue;
                }
                const exact_res = self.tryExact(alo, ahi, blo, bhi, probe, probe, exhaustive);
                if ((exact_res == null)) {
                    continue;
                }
                var fr = exact_res.?;
                _ = &fr;
                if (exhaustive) {
                    const n = ((ahi - alo) + (bhi - blo));
                    const wl_pos: usize = (if ((self.work_left > 0)) @intCast(self.work_left) else 0);
                    const depth = @min(self.policy.exhaustiveDepth(n), std.math.sqrt((wl_pos / 2)));
                    if ((depth > probe)) {
                        if (self.tryExact(alo, ahi, blo, bhi, depth, probe, true)) |v2| {
                            _ = &v2;
                            fr = v2;
                        } else {
                            continue;
                        }
                    }
                    if (((T == u32) and self.splitAtAnchors(alo, ahi, blo, bhi))) {
                        continue;
                    }
                }
                const f = fr.f;
                const r = fr.r;
                const start_pt = Point{ .x = alo, .y = blo };
                const end_pt = Point{ .x = ahi, .y = bhi };
                const f_inside = ((!f.eq(start_pt)) and (!f.eq(end_pt)));
                const r_inside = ((!r.eq(start_pt)) and (!r.eq(end_pt)));
                var cuts: [4]Point = .{ start_pt, start_pt, start_pt, start_pt };
                _ = &cuts;
                var n: usize = 1;
                _ = &n;
                if (f_inside) {
                    cuts[cp_cast_int(usize, n)] = f;
                    n = (n + 1);
                }
                if ((r_inside and ((n == 1) or (((f.x <= r.x) and (f.y <= r.y)) and (!f.eq(r)))))) {
                    cuts[cp_cast_int(usize, n)] = r;
                    n = (n + 1);
                }
                if ((n == 1)) {
                    _ = @memset(changed_a[alo..ahi], true);
                    _ = @memset(changed_b[blo..bhi], true);
                    continue;
                }
                cuts[cp_cast_int(usize, n)] = end_pt;
                const next_probe = @max((probe / 2), MIN_PROBE);
                var c: usize = 0;
                _ = &c;
                while ((c < n)) : (c = (c + 1)) {
                    _ = bun.handleOom(self.sc.stack.append(self.allocator, Job{ .alo = cuts[@as(usize, @intCast(c))].x, .ahi = cuts[@as(usize, @intCast((c + 1)))].x, .blo = cuts[@as(usize, @intCast(c))].y, .bhi = cuts[@as(usize, @intCast((c + 1)))].y, .probe = next_probe, .exhaustive = false }));
                }
            }
    }

pub fn tryExact(self: *@This(), alo: usize, ahi: usize, blo: usize, bhi: usize, depth: usize, probe: usize, exhaustive: bool) ?GreedySplit {
            const sp = self.middle(alo, ahi, blo, bhi, depth);
            switch (sp) {
.exact => |pt| {
if ((((pt.x != alo) or (pt.y != blo)) and ((pt.x != ahi) or (pt.y != bhi)))) {
                _ = bun.handleOom(self.sc.stack.append(self.allocator, Job{ .alo = alo, .ahi = pt.x, .blo = blo, .bhi = pt.y, .probe = probe, .exhaustive = exhaustive }));
                _ = bun.handleOom(self.sc.stack.append(self.allocator, Job{ .alo = pt.x, .ahi = ahi, .blo = pt.y, .bhi = bhi, .probe = probe, .exhaustive = exhaustive }));
                return null;
            }
            return GreedySplit{ .f = Point{ .x = alo, .y = blo }, .r = Point{ .x = alo, .y = blo } };
},
.greedy => |g| {
return g;
},
}
    }

pub fn splitAtAnchors(self: *@This(), alo: usize, ahi: usize, blo: usize, bhi: usize) bool {
            const probe = self.policy.probe;
            self.work_left = (self.work_left - @as(isize, @intCast(((ahi - alo) + (bhi - blo)))));
            if ((self.anchors == null)) {
                var max_id: usize = 0;
                _ = &max_id;
                for (cp_iter_slice(self.a)) |t| {
                    _ = &t;
                    const id = (if (comptime @typeInfo(@TypeOf(t)) == .@"enum") cp_cast_int(usize, @intFromEnum(t)) else cp_cast_int(usize, t));
                    if ((id > max_id)) {
                        max_id = id;
                    }
                }
                for (cp_iter_slice(self.b)) |t| {
                    _ = &t;
                    const id = (if (comptime @typeInfo(@TypeOf(t)) == .@"enum") cp_cast_int(usize, @intFromEnum(t)) else cp_cast_int(usize, t));
                    if ((id > max_id)) {
                        max_id = id;
                    }
                }
                self.anchors = Anchors.init(self.allocator, (1 + max_id));
            }
            const an = (&self.anchors.?);
            for (cp_iter_slice(self.a[alo..ahi])) |t| {
                _ = &t;
                an.count_a[cp_cast_int(usize, (if (comptime @typeInfo(@TypeOf(t)) == .@"enum") cp_cast_int(usize, @intFromEnum(t)) else cp_cast_int(usize, t)))] = (an.count_a[@as(usize, @intCast((if (comptime @typeInfo(@TypeOf(t)) == .@"enum") cp_cast_int(usize, @intFromEnum(t)) else cp_cast_int(usize, t))))] + 1);
            }
            var j_off: usize = 0;
            _ = &j_off;
            for (cp_iter_slice(self.b[blo..bhi])) |t| {
                _ = &t;
                const id = (if (comptime @typeInfo(@TypeOf(t)) == .@"enum") cp_cast_int(usize, @intFromEnum(t)) else cp_cast_int(usize, t));
                an.count_b[cp_cast_int(usize, id)] = (an.count_b[@as(usize, @intCast(id))] + 1);
                an.pos_b[cp_cast_int(usize, id)] = (if (comptime @typeInfo(@TypeOf((blo + j_off))) == .@"enum") cp_cast_int(u32, @intFromEnum((blo + j_off))) else cp_cast_int(u32, (blo + j_off)));
                j_off = (j_off + 1);
            }
            _ = an.pairs.clearRetainingCapacity();
            var i_off: usize = 0;
            _ = &i_off;
            for (cp_iter_slice(self.a[alo..ahi])) |t| {
                _ = &t;
                const id = (if (comptime @typeInfo(@TypeOf(t)) == .@"enum") cp_cast_int(usize, @intFromEnum(t)) else cp_cast_int(usize, t));
                if (((an.count_a[@as(usize, @intCast(id))] == 1) and (an.count_b[@as(usize, @intCast(id))] == 1))) {
                    _ = bun.handleOom(an.pairs.append(self.allocator, Pair{ .a = (if (comptime @typeInfo(@TypeOf((alo + i_off))) == .@"enum") cp_cast_int(u32, @intFromEnum((alo + i_off))) else cp_cast_int(u32, (alo + i_off))), .b = an.pos_b[@as(usize, @intCast(id))] }));
                }
                i_off = (i_off + 1);
            }
            for (cp_iter_slice(self.a[alo..ahi])) |t| {
                _ = &t;
                an.count_a[cp_cast_int(usize, (if (comptime @typeInfo(@TypeOf(t)) == .@"enum") cp_cast_int(usize, @intFromEnum(t)) else cp_cast_int(usize, t)))] = 0;
            }
            for (cp_iter_slice(self.b[blo..bhi])) |t| {
                _ = &t;
                an.count_b[cp_cast_int(usize, (if (comptime @typeInfo(@TypeOf(t)) == .@"enum") cp_cast_int(usize, @intFromEnum(t)) else cp_cast_int(usize, t)))] = 0;
            }
            const needed = @max((@min((ahi - alo), (bhi - blo)) / ANCHOR_COVERAGE), 1);
            if ((an.pairs.items.len < needed)) {
                return false;
            }
            _ = an.tails.clearRetainingCapacity();
            _ = an.prev.clearRetainingCapacity();
            _ = bun.handleOom(an.prev.resize(self.allocator, an.pairs.items.len));
            _ = @memset(an.prev.items, std.math.maxInt(u32));
            var idx: usize = 0;
            _ = &idx;
            for (an.pairs.items) |pair| {
                _ = &pair;
                const jb = pair.b;
                var lo_p: usize = 0;
                _ = &lo_p;
                var hi_p: usize = an.tails.items.len;
                _ = &hi_p;
                while ((lo_p < hi_p)) {
                    const mid_p = (lo_p + ((hi_p - lo_p) / 2));
                    if ((an.pairs.items[@as(usize, @intCast((if (comptime @typeInfo(@TypeOf(an.tails.items[@as(usize, @intCast(mid_p))])) == .@"enum") cp_cast_int(usize, @intFromEnum(an.tails.items[@as(usize, @intCast(mid_p))])) else cp_cast_int(usize, an.tails.items[@as(usize, @intCast(mid_p))]))))].b < jb)) {
                        lo_p = (mid_p + 1);
                    } else {
                        hi_p = mid_p;
                    }
                }
                const pos = lo_p;
                if ((pos > 0)) {
                    an.prev.items[cp_cast_int(usize, idx)] = an.tails.items[@as(usize, @intCast((pos - 1)))];
                }
                if ((pos == an.tails.items.len)) {
                    _ = bun.handleOom(an.tails.append(self.allocator, (if (comptime @typeInfo(@TypeOf(idx)) == .@"enum") cp_cast_int(u32, @intFromEnum(idx)) else cp_cast_int(u32, idx))));
                } else {
                    an.tails.items[cp_cast_int(usize, pos)] = (if (comptime @typeInfo(@TypeOf(idx)) == .@"enum") cp_cast_int(u32, @intFromEnum(idx)) else cp_cast_int(u32, idx));
                }
                idx = (idx + 1);
            }
            if ((an.tails.items.len < needed)) {
                return false;
            }
            var cur = an.tails.items[@as(usize, @intCast((an.tails.items.len - 1)))];
            _ = &cur;
            _ = an.tails.clearRetainingCapacity();
            while ((cur != std.math.maxInt(u32))) {
                _ = bun.handleOom(an.tails.append(self.allocator, cur));
                cur = an.prev.items[@as(usize, @intCast((if (comptime @typeInfo(@TypeOf(cur)) == .@"enum") cp_cast_int(usize, @intFromEnum(cur)) else cp_cast_int(usize, cur))))];
            }
            var ea = ahi;
            _ = &ea;
            var eb = bhi;
            _ = &eb;
            for (an.tails.items) |pi| {
                _ = &pi;
                const pr = an.pairs.items[@as(usize, @intCast((if (comptime @typeInfo(@TypeOf(pi)) == .@"enum") cp_cast_int(usize, @intFromEnum(pi)) else cp_cast_int(usize, pi))))];
                const pi_a = (if (comptime @typeInfo(@TypeOf(pr.a)) == .@"enum") cp_cast_int(usize, @intFromEnum(pr.a)) else cp_cast_int(usize, pr.a));
                const pi_b = (if (comptime @typeInfo(@TypeOf(pr.b)) == .@"enum") cp_cast_int(usize, @intFromEnum(pr.b)) else cp_cast_int(usize, pr.b));
                if ((((pi_a + 1) < ea) or ((pi_b + 1) < eb))) {
                    _ = bun.handleOom(self.sc.stack.append(self.allocator, Job{ .alo = (pi_a + 1), .ahi = ea, .blo = (pi_b + 1), .bhi = eb, .probe = probe, .exhaustive = true }));
                }
                ea = pi_a;
                eb = pi_b;
            }
            if (((alo < ea) or (blo < eb))) {
                _ = bun.handleOom(self.sc.stack.append(self.allocator, Job{ .alo = alo, .ahi = ea, .blo = blo, .bhi = eb, .probe = probe, .exhaustive = true }));
            }
            return true;
    }

pub fn middle(self: *@This(), alo: usize, ahi: usize, blo: usize, bhi: usize, depth: usize) Split {
            const a = self.a[alo..ahi];
            const b = self.b[blo..bhi];
            const n: i32 = @intCast(a.len);
            const m: i32 = @intCast(b.len);
            const delta = (n - m);
            const dmax = @divTrunc(((n + m) + 1), 2);
            const bmax = @min(dmax, @as(i32, @intCast(depth)));
            const off = (bmax + 1);
            const size: usize = @intCast(((2 * bmax) + 3));
            _ = bun.handleOom(self.sc.vf.resize(self.allocator, size));
            _ = @memset(self.sc.vf.items, NONE);
            _ = bun.handleOom(self.sc.vb.resize(self.allocator, size));
            _ = @memset(self.sc.vb.items, NONE);
            const vf = self.sc.vf.items;
            const vb = self.sc.vb.items;
            const off_1: usize = @intCast((off + 1));
            vf[cp_cast_int(usize, off_1)] = 0;
            vb[cp_cast_int(usize, off_1)] = 0;
            const front = ((delta & 1) != 0);
            var d: i32 = 0;
            _ = &d;
            while ((d <= bmax)) : (d = (d + 1)) {
                {
                    const bounds = diagRange(d, n, m);
                    var k = bounds.lo;
                    _ = &k;
                    const kmax = bounds.hi;
                    const clo = (delta - (d - 1));
                    const chi = (delta + (d - 1));
                    var lim = (if ((n < (m + k))) n else (m + k));
                    _ = &lim;
                    var i: usize = @intCast((k + off));
                    _ = &i;
                    var lo = vf[@as(usize, @intCast((i - 1)))];
                    _ = &lo;
                    while ((k <= kmax)) {
                        const hi = vf[@as(usize, @intCast((i + 1)))];
                        var x = (if (((lo + 1) > hi)) (lo + 1) else hi);
                        _ = &x;
                        if ((x > lim)) {
                            x = (if (((lo + 1) < hi)) (lo + 1) else hi);
                            if (((x < 0) or (x > lim))) {
                                x = vf[@as(usize, @intCast(i))];
                            }
                        }
                        if ((x >= 0)) {
                            const y = (x - k);
                            if (((x < n) and (y < m))) {
                                const ux: usize = @intCast(x);
                                const uy: usize = @intCast(y);
                                if ((a[@as(usize, @intCast(ux))] == b[@as(usize, @intCast(uy))])) {
                                    x = (x + (1 + @as(i32, @intCast(commonPrefix(T, a[(ux + 1)..], b[(uy + 1)..])))));
                                }
                            }
                            vf[cp_cast_int(usize, i)] = x;
                            if (((front and (k >= clo)) and (k <= chi))) {
                                const rev_idx: usize = @intCast(((delta - k) + off));
                                const x2 = vb[@as(usize, @intCast(rev_idx))];
                                if (((x2 >= 0) and ((x + x2) >= n))) {
                                    const d_isize: isize = @intCast(d);
                                    self.work_left = (self.work_left - ((d_isize + 1) * (d_isize + 1)));
                                    return Split{ .exact = Point{ .x = (alo + @as(usize, @intCast(x))), .y = (blo + @as(usize, @intCast((x - k)))) } };
                                }
                            }
                        }
                        lo = hi;
                        k = (k + 2);
                        i = (i + 2);
                        lim = (if (((lim + 2) < n)) (lim + 2) else n);
                    }
                }
                {
                    const bounds = diagRange(d, n, m);
                    var k2 = bounds.lo;
                    _ = &k2;
                    const kmax = bounds.hi;
                    const clo = (delta - d);
                    const chi = (delta + d);
                    var lim = (if ((n < (m + k2))) n else (m + k2));
                    _ = &lim;
                    var i: usize = @intCast((k2 + off));
                    _ = &i;
                    var lo = vb[@as(usize, @intCast((i - 1)))];
                    _ = &lo;
                    while ((k2 <= kmax)) {
                        const hi = vb[@as(usize, @intCast((i + 1)))];
                        var x2 = (if (((lo + 1) > hi)) (lo + 1) else hi);
                        _ = &x2;
                        if ((x2 > lim)) {
                            x2 = (if (((lo + 1) < hi)) (lo + 1) else hi);
                            if (((x2 < 0) or (x2 > lim))) {
                                x2 = vb[@as(usize, @intCast(i))];
                            }
                        }
                        if ((x2 >= 0)) {
                            const y2 = (x2 - k2);
                            if (((x2 < n) and (y2 < m))) {
                                const ux2: usize = @intCast(x2);
                                const uy2: usize = @intCast(y2);
                                if ((a[@as(usize, @intCast(((a.len - 1) - ux2)))] == b[@as(usize, @intCast(((b.len - 1) - uy2)))])) {
                                    x2 = (x2 + (1 + @as(i32, @intCast(commonSuffix(T, a[0..((a.len - 1) - ux2)], b[0..((b.len - 1) - uy2)])))));
                                }
                            }
                            vb[cp_cast_int(usize, i)] = x2;
                            if ((((!front) and (k2 >= clo)) and (k2 <= chi))) {
                                const k = (delta - k2);
                                const fwd_idx: usize = @intCast((k + off));
                                const x = vf[@as(usize, @intCast(fwd_idx))];
                                if (((x >= 0) and ((x2 + x) >= n))) {
                                    const d_isize: isize = @intCast(d);
                                    self.work_left = (self.work_left - ((d_isize + 1) * (d_isize + 2)));
                                    return Split{ .exact = Point{ .x = (alo + @as(usize, @intCast(x))), .y = (blo + @as(usize, @intCast((x - k)))) } };
                                }
                            }
                        }
                        lo = hi;
                        k2 = (k2 + 2);
                        i = (i + 2);
                        lim = (if (((lim + 2) < n)) (lim + 2) else n);
                    }
                }
            }
            const bmax_isize: isize = @intCast(bmax);
            self.work_left = (self.work_left - ((bmax_isize + 1) * (bmax_isize + 2)));
            const f_best = bestPoint(vf, bmax, off, m);
            const b_best = bestPoint(vb, bmax, off, m);
            return Split{ .greedy = GreedySplit{ .f = Point{ .x = (alo + @as(usize, @intCast(f_best.x))), .y = (blo + @as(usize, @intCast(f_best.y))) }, .r = Point{ .x = (alo + @as(usize, @intCast((n - b_best.x)))), .y = (blo + @as(usize, @intCast((m - b_best.y)))) } } };
    }
};
}

pub fn bestPoint(v: []const i32, bmax: i32, off: i32, m: i32) IPoint {
        var best_prog: i32 = -1;
        _ = &best_prog;
        var best_x: i32 = 0;
        _ = &best_x;
        var best_y: i32 = 0;
        _ = &best_y;
        var k = (-bmax);
        _ = &k;
        while ((k <= bmax)) : (k = (k + 1)) {
            const idx: usize = @intCast((k + off));
            const x = v[@as(usize, @intCast(idx))];
            if ((((x >= 0) and ((x - k) <= m)) and (((2 * x) - k) > best_prog))) {
                best_prog = ((2 * x) - k);
                best_x = x;
                best_y = (x - k);
            }
        }
        return IPoint{ .x = best_x, .y = best_y };
}

pub fn pushTrimmed(comptime T: type, allocator: std.mem.Allocator, a: []const T, b: []const T, h_in: Hunk, out: *std.ArrayListUnmanaged(Hunk)) void {
