pub fn mkOneVsLinesHunk(o_lo: usize, o_hi: usize, m_lo: usize, m_hi: usize, base: usize, swapped: bool) Hunk {
        if (swapped) {
            return Hunk{ .a_lo = (base + m_lo), .a_hi = (base + m_hi), .b_lo = (base + o_lo), .b_hi = (base + o_hi) };
        }
        return Hunk{ .a_lo = (base + o_lo), .a_hi = (base + o_hi), .b_lo = (base + m_lo), .b_hi = (base + m_hi) };
