                _ = &idx;
                return ContainsResult{ .long_is_a = false, .at = idx };
            }
            return null;
        }
}

pub fn cleanupMerge(allocator: std.mem.Allocator, hunks: *std.ArrayListUnmanaged(Hunk), a: []const u8, b: []const u8) void {
        _ = &allocator;
        while (true) {
            var w: usize = 0;
            _ = &w;
            for (hunks.items) |r_h| {
                _ = &r_h;
                var h = r_h;
                _ = &h;
                if (((h.a_lo < h.a_hi) and (h.b_lo < h.b_hi))) {
                    const p = commonPrefix(u8, a[h.a_lo..h.a_hi], b[h.b_lo..h.b_hi]);
                    h.a_lo = (h.a_lo + p);
                    h.b_lo = (h.b_lo + p);
                    const s = commonSuffix(u8, a[h.a_lo..h.a_hi], b[h.b_lo..h.b_hi]);
                    h.a_hi = (h.a_hi - s);
                    h.b_hi = (h.b_hi - s);
                    if (((h.a_lo == h.a_hi) and (h.b_lo == h.b_hi))) {
                        continue;
                    }
                }
                if ((((w > 0) and (hunks.items[@as(usize, @intCast((w - 1)))].a_hi == h.a_lo)) and (hunks.items[@as(usize, @intCast((w - 1)))].b_hi == h.b_lo))) {
                    hunks.items[@as(usize, @intCast((w - 1)))].a_hi = h.a_hi;
                    hunks.items[@as(usize, @intCast((w - 1)))].b_hi = h.b_hi;
                } else {
                    hunks.items[cp_cast_int(usize, w)] = h;
                    w = (w + 1);
                }
            }
            hunks.items.len = w;
            if ((!slideSingleEdits(u8, hunks.items, a, b, false))) {
                return;
            }
        }
}

pub fn cleanupSemantic(allocator: std.mem.Allocator, hunks: *std.ArrayListUnmanaged(Hunk), scratch: *std.ArrayListUnmanaged(Hunk), a: []const u8, b: []const u8, kmp: *std.ArrayListUnmanaged(u32)) void {
        var changed = false;
        _ = &changed;
        var w: usize = 0;
        _ = &w;
        for (hunks.items) |r_h| {
            _ = &r_h;
            var cur = r_h;
            _ = &cur;
            while ((w > 0)) {
                const l = hunks.items[@as(usize, @intCast((w - 1)))];
                const gap = (cur.a_lo - l.a_hi);
                if (((gap <= @max(l.deleted(), l.inserted())) and (gap <= @max(cur.deleted(), cur.inserted())))) {
                    cur = Hunk{ .a_lo = l.a_lo, .a_hi = cur.a_hi, .b_lo = l.b_lo, .b_hi = cur.b_hi };
                    w = (w - 1);
                    changed = true;
                } else {
                    break;
                }
            }
            hunks.items[cp_cast_int(usize, w)] = cur;
            w = (w + 1);
        }
        hunks.items.len = w;
        if (changed) {
            _ = cleanupMerge(allocator, hunks, a, b);
        }
        _ = cleanupSemanticLossless(hunks, a, b);
        _ = scratch.clearRetainingCapacity();
        for (hunks.items) |h| {
            _ = &h;
            const del = a[h.a_lo..h.a_hi];
            const ins = b[h.b_lo..h.b_hi];
            if (((del.len == 0) or (ins.len == 0))) {
                _ = bun.handleOom(scratch.append(allocator, h));
                continue;
            }
            const fwd = commonOverlap(allocator, del, ins, kmp);
            const rev = commonOverlap(allocator, ins, del, kmp);
            if ((fwd >= rev)) {
                if (((fwd > 0) and (((fwd * 2) >= del.len) or ((fwd * 2) >= ins.len)))) {
                    _ = pushNonempty(allocator, scratch, Hunk{ .a_lo = h.a_lo, .a_hi = (h.a_hi - fwd), .b_lo = h.b_lo, .b_hi = h.b_lo });
                    _ = pushNonempty(allocator, scratch, Hunk{ .a_lo = h.a_hi, .a_hi = h.a_hi, .b_lo = (h.b_lo + fwd), .b_hi = h.b_hi });
                    continue;
                }
            } else {
                if ((((rev * 2) >= del.len) or ((rev * 2) >= ins.len))) {
                    _ = pushNonempty(allocator, scratch, Hunk{ .a_lo = h.a_lo, .a_hi = h.a_lo, .b_lo = h.b_lo, .b_hi = (h.b_hi - rev) });
                    _ = pushNonempty(allocator, scratch, Hunk{ .a_lo = (h.a_lo + rev), .a_hi = h.a_hi, .b_lo = h.b_hi, .b_hi = h.b_hi });
                    continue;
                }
            }
            _ = bun.handleOom(scratch.append(allocator, h));
        }
        _ = std.mem.swap(std.ArrayListUnmanaged(Hunk), hunks, scratch);
}

pub fn cleanupSemanticLossless(hunks: *std.ArrayListUnmanaged(Hunk), a: []const u8, b: []const u8) void {
        var w: usize = 0;
        _ = &w;
        var r: usize = 0;
        _ = &r;
        while ((r < hunks.items.len)) : (r = (r + 1)) {
            const h_orig = hunks.items[@as(usize, @intCast(r))];
            const prev_a = (if ((w == 0)) 0 else hunks.items[@as(usize, @intCast((w - 1)))].a_hi);
            const next_a = (if (((r + 1) == hunks.items.len)) a.len else hunks.items[@as(usize, @intCast((r + 1)))].a_lo);
            const before = (h_orig.a_lo - prev_a);
            const after = (next_a - h_orig.a_hi);
            if ((((before == 0) or (after == 0)) or ((h_orig.deleted() > 0) and (h_orig.inserted() > 0)))) {
                hunks.items[cp_cast_int(usize, w)] = h_orig;
                w = (w + 1);
                continue;
            }
            const is_del = (h_orig.deleted() > 0);
            const seq = (if (is_del) a else b);
            var lo = (if (is_del) h_orig.a_lo else h_orig.b_lo);
            _ = &lo;
            var hi = (if (is_del) h_orig.a_hi else h_orig.b_hi);
            _ = &hi;
            const orig_lo = lo;
            const eq1_start = (lo - before);
            const eq2_end = (hi + after);
            var shift = commonSuffix(u8, seq[eq1_start..lo], seq[lo..hi]);
            _ = &shift;
            while (((shift > 0) and isUtf8Cont(seq, (lo - shift)))) {
                shift = (shift - 1);
            }
            lo = (lo - shift);
            hi = (hi - shift);
            var best_lo = lo;
            _ = &best_lo;
            var best_score = (semanticScore(seq[eq1_start..lo], seq[lo..hi]) + semanticScore(seq[lo..hi], seq[hi..eq2_end]));
            _ = &best_score;
            while (((hi < eq2_end) and (seq[@as(usize, @intCast(lo))] == seq[@as(usize, @intCast(hi))]))) {
                lo = (lo + 1);
                hi = (hi + 1);
                if (isUtf8Cont(seq, lo)) {
                    continue;
                }
                const score = (semanticScore(seq[eq1_start..lo], seq[lo..hi]) + semanticScore(seq[lo..hi], seq[hi..eq2_end]));
                if ((score >= best_score)) {
                    best_lo = lo;
                    best_score = score;
                }
            }
            const delta: isize = (@as(isize, @intCast(best_lo)) - @as(isize, @intCast(orig_lo)));
            const h = Hunk{ .a_lo = @intCast((@as(isize, @intCast(h_orig.a_lo)) + delta)), .a_hi = @intCast((@as(isize, @intCast(h_orig.a_hi)) + delta)), .b_lo = @intCast((@as(isize, @intCast(h_orig.b_lo)) + delta)), .b_hi = @intCast((@as(isize, @intCast(h_orig.b_hi)) + delta)) };
            if (((((r + 1) < hunks.items.len) and (h.a_hi == hunks.items[@as(usize, @intCast((r + 1)))].a_lo)) and (h.b_hi == hunks.items[@as(usize, @intCast((r + 1)))].b_lo))) {
                hunks.items[@as(usize, @intCast((r + 1)))].a_lo = h.a_lo;
                hunks.items[@as(usize, @intCast((r + 1)))].b_lo = h.b_lo;
            } else {
                if ((((w > 0) and (hunks.items[@as(usize, @intCast((w - 1)))].a_hi == h.a_lo)) and (hunks.items[@as(usize, @intCast((w - 1)))].b_hi == h.b_lo))) {
                    hunks.items[@as(usize, @intCast((w - 1)))].a_hi = h.a_hi;
                    hunks.items[@as(usize, @intCast((w - 1)))].b_hi = h.b_hi;
                } else {
                    hunks.items[cp_cast_int(usize, w)] = h;
                    w = (w + 1);
                }
            }
        }
        hunks.items.len = w;
}

pub fn isAsciiAlnum(c: u8) bool {
        return ((((c >= 48) and (c <= 57)) or ((c >= 65) and (c <= 90))) or ((c >= 97) and (c <= 122)));
}

pub fn isAsciiWhitespace(c: u8) bool {
        return ((((((c == 32) or (c == 9)) or (c == 10)) or (c == 13)) or (c == 11)) or (c == 12));
}

pub fn isAsciiControl(c: u8) bool {
        return ((c < 32) or (c == 127));
}

pub fn semanticScore(one: []const u8, two: []const u8) u32 {
        if (((one.len == 0) or (two.len == 0))) {
            return 6;
        }
        const char1 = one[@as(usize, @intCast((one.len - 1)))];
        const char2 = two[0];
        const non_alphanumeric1 = (!isAsciiAlnum(char1));
        const non_alphanumeric2 = (!isAsciiAlnum(char2));
        const whitespace1 = (non_alphanumeric1 and isAsciiWhitespace(char1));
        const whitespace2 = (non_alphanumeric2 and isAsciiWhitespace(char2));
        const line_break1 = (whitespace1 and isAsciiControl(char1));
        const line_break2 = (whitespace2 and isAsciiControl(char2));
        const blank_line1 = (line_break1 and (std.mem.endsWith(u8, one, "\n\n") or std.mem.endsWith(u8, one, "\n\r\n")));
        const blank_line2 = (line_break2 and (((std.mem.startsWith(u8, two, "\n\n") or std.mem.startsWith(u8, two, "\r\n\n")) or std.mem.startsWith(u8, two, "\n\r\n")) or std.mem.startsWith(u8, two, "\r\n\r\n")));
        if ((blank_line1 or blank_line2)) {
            return 5;
        }
        if ((line_break1 or line_break2)) {
            return 4;
        }
        if (((non_alphanumeric1 and (!whitespace1)) and whitespace2)) {
            return 3;
        }
        if ((whitespace1 or whitespace2)) {
            return 2;
        }
        if ((non_alphanumeric1 or non_alphanumeric2)) {
            return 1;
        }
        return 0;
}

pub fn commonOverlap(allocator: std.mem.Allocator, x_in: []const u8, y_in: []const u8, fail: *std.ArrayListUnmanaged(u32)) usize {
        const n = @min(@min(x_in.len, y_in.len), OVERLAP_MAX);
        if ((n == 0)) {
            return 0;
        }
        const x = x_in[(x_in.len - n)..];
        const y = y_in[0..n];
        if (std.mem.eql(u8, x, y)) {
            return n;
        }
        if ((n <= 16)) {
            var k = (n - 1);
            _ = &k;
            while ((k >= 1)) : (k = (k - 1)) {
                if (std.mem.eql(u8, x[(n - k)..], y[0..k])) {
                    return k;
                }
            }
            return 0;
        }
        _ = bun.handleOom(fail.resize(allocator, n));
        _ = @memset(fail.items, 0);
        var k: usize = 0;
        _ = &k;
        var i: usize = 1;
        _ = &i;
        while ((i < n)) : (i = (i + 1)) {
            while (((k > 0) and (y[@as(usize, @intCast(i))] != y[@as(usize, @intCast(k))]))) {
                k = (if (comptime @typeInfo(@TypeOf(fail.items[@as(usize, @intCast((k - 1)))])) == .@"enum") cp_cast_int(usize, @intFromEnum(fail.items[@as(usize, @intCast((k - 1)))])) else cp_cast_int(usize, fail.items[@as(usize, @intCast((k - 1)))]));
            }
            if ((y[@as(usize, @intCast(i))] == y[@as(usize, @intCast(k))])) {
                k = (k + 1);
            }
            fail.items[cp_cast_int(usize, i)] = (if (comptime @typeInfo(@TypeOf(k)) == .@"enum") cp_cast_int(u32, @intFromEnum(k)) else cp_cast_int(u32, k));
        }
        var k2: usize = 0;
        _ = &k2;
        for (cp_iter_slice(x)) |c| {
            _ = &c;
            while (((k2 > 0) and (c != y[@as(usize, @intCast(k2))]))) {
                k2 = (if (comptime @typeInfo(@TypeOf(fail.items[@as(usize, @intCast((k2 - 1)))])) == .@"enum") cp_cast_int(usize, @intFromEnum(fail.items[@as(usize, @intCast((k2 - 1)))])) else cp_cast_int(usize, fail.items[@as(usize, @intCast((k2 - 1)))]));
            }
            if ((c == y[@as(usize, @intCast(k2))])) {
                k2 = (k2 + 1);
            }
            if ((k2 == n)) {
                k2 = (if (comptime @typeInfo(@TypeOf(fail.items[@as(usize, @intCast((k2 - 1)))])) == .@"enum") cp_cast_int(usize, @intFromEnum(fail.items[@as(usize, @intCast((k2 - 1)))])) else cp_cast_int(usize, fail.items[@as(usize, @intCast((k2 - 1)))]));
            }
        }
        return k2;
}

pub fn isUtf8Cont(s: []const u8, i: usize) bool {
        return ((i < s.len) and ((s[@as(usize, @intCast(i))] & 192) == 128));
}

pub fn alignToUtf8(hunks: *std.ArrayListUnmanaged(Hunk), a: []const u8) void {
        var w: usize = 0;
        _ = &w;
        var r: usize = 0;
        _ = &r;
        while ((r < hunks.items.len)) {
            var h = hunks.items[@as(usize, @intCast(r))];
            _ = &h;
            r = (r + 1);
            const floor = (if ((w == 0)) 0 else hunks.items[@as(usize, @intCast((w - 1)))].a_hi);
            while (((h.a_lo > floor) and isUtf8Cont(a, h.a_lo))) {
                h.a_lo = (h.a_lo - 1);
                h.b_lo = (h.b_lo - 1);
            }
            while (true) {
                const ceil = (if ((r < hunks.items.len)) hunks.items[@as(usize, @intCast(r))].a_lo else a.len);
                while (((h.a_hi < ceil) and isUtf8Cont(a, h.a_hi))) {
                    h.a_hi = (h.a_hi + 1);
                    h.b_hi = (h.b_hi + 1);
                }
                if (((r < hunks.items.len) and (h.a_hi == hunks.items[@as(usize, @intCast(r))].a_lo))) {
                    h.a_hi = hunks.items[@as(usize, @intCast(r))].a_hi;
                    h.b_hi = hunks.items[@as(usize, @intCast(r))].b_hi;
                    r = (r + 1);
                    continue;
                }
                break;
            }
            hunks.items[cp_cast_int(usize, w)] = h;
            w = (w + 1);
        }
        hunks.items.len = w;
}
